/* Scoped interaction repairs: prose and code outside the effect remain selectable. */
#modalArchiveBtn{margin-left:auto;margin-right:8px}.toolbar .tabs{min-width:0}.toolbar-actions{flex-shrink:0}.meta>span{min-width:0}.archive-btn{flex-shrink:0}.stage[data-mode=drag]{touch-action:none}.vault-dragging,.vault-dragging *{user-select:none!important;-webkit-user-select:none!important}.detail-stage{user-select:none;-webkit-user-select:none}.doc-content,.detail-copy p{user-select:text;-webkit-user-select:text}

/* One gallery with shared collection, review and archive views. */
[hidden]{display:none!important}
.view-tabs{display:flex;align-items:center;gap:25px;min-height:36px;margin:0 0 12px}
.view-tabs>button{border:0;background:none;color:var(--muted);font-size:12px;padding:5px 0;white-space:nowrap}
.view-tabs>button[aria-pressed=true]{color:var(--text);font-weight:600}
.view-tabs>button span{font-size:10px;margin-left:4px;font-variant-numeric:tabular-nums;color:var(--muted)}
.view-tabs .review-export{margin-left:auto;font-size:11px}
.collect-btn{margin-left:auto;color:var(--accent);font-size:10px;padding:2px 5px;flex-shrink:0}
.collect-btn+.archive-btn{margin-left:0}
.meta .archive-btn{white-space:nowrap}
#modalCollectBtn{margin-left:auto}
#modalCollectBtn:not([hidden])+#modalArchiveBtn{margin-left:2px}
.local-source-frame{position:absolute;inset:0;width:1100px;height:670px;border:0;transform-origin:0 0;background:var(--paper)}
.private-review{margin-top:18px;border-top:1px solid var(--line);padding-top:12px}
.private-review label{display:flex;justify-content:space-between;gap:16px;font-size:11px;color:var(--muted)}
.private-review label span{font-size:10px;text-align:right}
.private-review textarea{display:block;width:100%;min-height:65px;resize:vertical;padding:8px;border:1px solid var(--line);background:var(--panel);font-size:12px;border-radius:4px;margin-top:7px;user-select:text;-webkit-user-select:text}
.export-box{padding:20px}
.export-box textarea{width:100%;height:320px;background:var(--panel);border:1px solid var(--line);padding:12px;font:11px/1.5 monospace;resize:vertical}
.card:hover .preview-badge{opacity:1}
.card:focus-within{scroll-margin-top:20px}
/* Explicit media/code switch; no second gallery or overlay intercepts the pointer. */
.preview-modes{display:inline-flex;align-items:center;gap:2px;padding:3px;border:1px solid var(--line);border-radius:7px;background:color-mix(in srgb,var(--surface) 30%,transparent);flex-shrink:0}
.preview-modes button{border:0;border-radius:4px;background:transparent;padding:5px 10px;font-size:11px;line-height:1.4;white-space:nowrap;color:var(--muted)}
.preview-modes button[aria-pressed=true]{background:var(--panel);color:var(--text);box-shadow:0 1px 3px #17231812}
.preview-modes button:hover{color:var(--text)}
.source-loading{position:absolute;left:50%;bottom:15px;transform:translateX(-50%);font-size:11px;white-space:nowrap;padding:5px 10px;border:1px solid var(--line);border-radius:5px;background:var(--panel);color:var(--muted);pointer-events:none}
.local-source-frame{pointer-events:auto}
@media(max-width:580px){.toolbar-actions{justify-content:space-between;padding:8px 0}.preview-modes button{padding:5px 9px}.toolbar-actions .count{margin-left:0}}
@media(max-width:580px){.view-tabs{gap:20px;flex-wrap:wrap}.view-tabs .review-export{font-size:10px}.view-tabs>button{font-size:11px}.private-review label{flex-wrap:wrap;gap:5px}}

